        // draft fields remain untouched and no retry/write is dispatched.
        if(inNarrow())q('bm-conflict-review').scrollIntoView?.({block:'nearest'});
      }
    }
    if(authorityLost(error))
      gate('完整书签 SDK 或授权已失效；请到可信扩展界面重新审阅。');
