  }else{
    const visit=(id,level)=>{
      const item=tree.byId.get(id);if(!item)return;
      if(!tree.roots.has(id)){include(item,level);if(!expanded.has(id))return}
      for(const childId of tree.children.get(id)||[])visit(childId,level+1);
